-- Generated from src/notebooks/configs/webFoundationsConfig.js.
insert into public.nodes (slug, label, description, best_practices, naming_conventions, study_urls)
values (
  'web-foundations',
  'Professioni e infrastruttura del Web',
  'Ruoli professionali, server, data center, server farm, reti e modelli cloud che rendono disponibili i servizi Web.',
  array[]::text[],
  array[]::text[],
  '[
    {"label":"MDN: How the Web Works","url":"https://developer.mozilla.org/docs/Learn/Common_questions/Web_mechanisms/How_does_the_Internet_work"},
    {"label":"Google Cloud: Cloud Computing","url":"https://cloud.google.com/learn/what-is-cloud-computing"}
  ]'::jsonb
)
on conflict (slug) do nothing;

insert into public.node_categories (node_id, category, is_primary)
select id, 'tools', true from public.nodes where slug = 'web-foundations'
on conflict (node_id, category) do nothing;

insert into public.node_categories (node_id, category, is_primary)
select id, category, false
from public.nodes
cross join (values ('frontend'), ('backend'), ('devops')) as categories(category)
where slug = 'web-foundations'
on conflict (node_id, category) do nothing;

insert into public.node_parents (parent_id, child_id, sort_order, is_primary)
select parent.id, child.id, 0, true
from public.nodes parent
cross join public.nodes child
where parent.slug = 'internet-browser' and child.slug = 'web-foundations'
on conflict (parent_id, child_id) do nothing;

insert into public.node_content_sections (node_id, sort_order, title, type, payload)
select id, 0, 'Professioni e infrastruttura Web', 'text',
  jsonb_build_object('text', $text$Il Web è costruito e mantenuto da persone con competenze diverse. Frontend e backend developer realizzano interfaccia e servizi; designer e professionisti UX progettano l'esperienza; QA verifica il comportamento; sistemisti e figure DevOps curano sistemi, rilasci e infrastruttura. I ruoli possono sovrapporsi.

Un server è un sistema che offre un servizio: può essere un computer fisico, una macchina virtuale o una risorsa cloud. Web server, applicazione e database sono componenti software che possono risiedere sulla stessa macchina o essere distribuiti.

I data center ospitano server, rete, alimentazione e raffreddamento. Una server farm coordina più macchine per gestire il carico e migliorare la disponibilità. Il cloud offre queste risorse come servizi gestiti, dai server virtuali IaaS alle piattaforme PaaS e alle funzioni serverless.$text$)
from public.nodes
where slug = 'web-foundations'
  and not exists (
    select 1 from public.node_content_sections
    where node_id = public.nodes.id and title = 'Professioni e infrastruttura Web'
  );

insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'web-foundations', 'Conosci i ruoli di un team Web e segui le richieste dai server ai data center, alle server farm e ai servizi cloud.', n.id, null,
  convert_from(decode('', 'base64'), 'UTF8')::jsonb
from public.nodes n where n.slug = 'web-foundations'
on conflict (slug) do nothing;
